const MAPS_TILESET = 'microsoft.base';
const MAPS_API_VER = '2022-08-01';

let mapsKey = null;

// ---- INSTALL: cache app shell ----
self.addEventListener('install', e => {
  e.waitUntil(
    caches.open(CACHE).then(c => c.addAll(APP_SHELL)).then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', e => {
  e.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

// ---- MESSAGES from frontend ----
self.addEventListener('message', async e => {
  if (!e.data) return;

  if (e.data.type === 'SET_MAPS_KEY' && e.data.key) {
    mapsKey = e.data.key;
    await precacheZambia();
  }

  if (e.data.type === 'CHECK_CACHE') {
    const cache = await caches.open(CACHE);
    const keys = await cache.keys();
    const tilesCached = keys.filter(r => r.url.includes('atlas.microsoft.com/map/tile')).length;
    if (tilesCached >= ZAMBIA_COORDS.length * 0.9) {
      broadcast({ type: 'CACHE_READY' });
    } else if (mapsKey) {
      await precacheZambia();
    }
  }
});

async function precacheZambia() {
  if (!mapsKey) return;
  const cache = await caches.open(CACHE);
  const existing = new Set(
    (await cache.keys())
      .filter(r => r.url.includes('atlas.microsoft.com/map/tile'))
      .map(r => r.url)
  );

  const todo = ZAMBIA_COORDS
    .map(([z, x, y]) => tileUrl(z, x, y))
    .filter(url => !existing.has(url));

  if (todo.length === 0) { broadcast({ type: 'CACHE_READY' }); return; }

  const BATCH = 15;
  let done = existing.size;
  const total = ZAMBIA_COORDS.length;

  for (let i = 0; i < todo.length; i += BATCH) {
    const batch = todo.slice(i, i + BATCH);
    await Promise.allSettled(batch.map(url =>
      fetch(url).then(r => r.ok ? cache.put(url, r) : null).catch(() => null)
    ));
    done += batch.length;
    broadcast({ type: 'CACHE_PROGRESS', pct: Math.min(100, (done / total) * 100) });
  }
  broadcast({ type: 'CACHE_READY' });
}

function tileUrl(z, x, y) {
  return `https://atlas.microsoft.com/map/tile?subscription-key=${mapsKey}&api-version=${MAPS_API_VER}&tilesetId=${MAPS_TILESET}&zoom=${z}&x=${x}&y=${y}`;
}

async function broadcast(msg) {
  const clients = await self.clients.matchAll({ includeUncontrolled: true });
  clients.forEach(c => c.postMessage(msg));
}

// ---- FETCH: cache-first for tiles, network-first for API ----
self.addEventListener('fetch', e => {
  const url = e.request.url;

  // Azure Maps tiles: cache-first
  if (url.includes('atlas.microsoft.com/map/tile')) {
    e.respondWith(
      caches.match(e.request).then(cached => {
        if (cached) return cached;
        return fetch(e.request).then(res => {
          if (res.ok) {
            const clone = res.clone();
            caches.open(CACHE).then(c => c.put(e.request, clone));
          }
          return res;
        }).catch(() => new Response('', { status: 503 }));
      })
    );
    return;
  }

  // App shell: cache-first
  if (APP_SHELL.some(path => url.endsWith(path) || url === self.registration.scope)) {
    e.respondWith(caches.match(e.request).then(c => c || fetch(e.request)));
    return;
  }

  // Azure Functions API: network-only (never cache)
  if (url.includes('/api/')) return;

  // Azure Maps SDK assets: stale-while-revalidate
  if (url.includes('atlas.microsoft.com/sdk')) {
    e.respondWith(
      caches.open(CACHE).then(async cache => {
        const cached = await cache.match(e.request);
        const fetchPromise = fetch(e.request).then(res => {
          cache.put(e.request, res.clone());
          return res;
        }).catch(() => cached);
        return cached || fetchPromise;
      })
    );
  }
});

